8	namespace Meridian.Application.Messages;
9	
10	public sealed record SubmitMessageCommand(string? Sender, string? Text);
11	
12	/// <summary>One job a message made or was attached to, in the order of the model's issues.</summary>
13	/// <param name="IsFollowUp">True when the message was attached to an existing job rather than starting it.</param>
14	public sealed record SubmittedJob(Guid JobId, string Reference, bool IsFollowUp);
15	
16	public sealed record SubmitMessageResult(
17	    Guid? MessageId,
18	    IReadOnlyList<SubmittedJob> Jobs,
19	    IReadOnlyDictionary<string, string[]> Errors)
20	{
21	    public bool Succeeded => Errors.Count == 0;
22	
23	    public static SubmitMessageResult Invalid(IReadOnlyDictionary<string, string[]> errors) =>
24	        new(null, Array.Empty<SubmittedJob>(), errors);
25	
26	    public static SubmitMessageResult Created(Guid messageId, IReadOnlyList<SubmittedJob> jobs) =>
27	        new(messageId, jobs, new Dictionary<string, string[]>());
28	}
29	
30	/// <summary>
31	/// The intake pipeline (AD-3): stores a pasted message unchanged, evaluates the emergency rules, asks the model
32	/// (<see cref="PrepareJob"/>), then turns the model's issues into jobs with plain code (AD-13):
33	/// <list type="number">
34	/// <item><see cref="PropertyResolver"/> matches each issue's <c>property_text</c>; unresolved or ambiguous → Unsure, property unset.</item>
35	/// <item><see cref="FollowUpMatcher"/> attaches an issue to an existing open job as a follow-up, which can raise its urgency.</item>
36	/// <item>Every other issue becomes its own job; one message can make several jobs.</item>
37	/// </list>
38	/// The message is committed before the model is called, so a model failure never loses it; when the model fails
39	/// the message makes one Unsure job, and a valid answer with no issues makes one Unsure job flagged for a person.
40	/// Every job the message touches gets the rule result (<c>RulesApplied</c>), so a rule emergency applies whatever
41	/// the model does (RULE-11).
42	/// In the same second unit of work the sender gets one fixed acknowledgement quoting every job reference the message
43	/// made or matched (<see cref="AcknowledgeTenant"/>, R16). A crash between the two saves leaves a message with no
44	/// job; <see cref="RecoverOrphanMessages"/> turns it into one Unsure job and acknowledges it (RULE-11).
45	/// </summary>
46	public sealed class SubmitMessage
47	{
48	    private readonly IJobRepository _jobs;
49	    private readonly IPropertyRepository _properties;
50	    private readonly IUnitOfWork _unitOfWork;
51	    private readonly IClock _clock;
52	    private readonly PrepareJob _prepareJob;
53	    private readonly AcknowledgeTenant _acknowledge;
54	
55	    public SubmitMessage(
56	        IJobRepository jobs,
57	        IPropertyRepository properties,
58	        IUnitOfWork unitOfWork,
59	        IClock clock,
60	        PrepareJob prepareJob,
61	        AcknowledgeTenant acknowledge)
62	    {
63	        _jobs = jobs;
64	        _properties = properties;
65	        _unitOfWork = unitOfWork;
66	        _clock = clock;
67	        _prepareJob = prepareJob;
68	        _acknowledge = acknowledge;
69	    }
70	
71	    public static IReadOnlyDictionary<string, string[]> Validate(SubmitMessageCommand command)
72	    {
73	        var errors = new Dictionary<string, string[]>();
74	        if (string.IsNullOrWhiteSpace(command.Sender))
75	        {
76	            errors["sender"] = new[] { "Sender is required." };
77	        }
78	
79	        if (string.IsNullOrWhiteSpace(command.Text))
80	        {
81	            errors["text"] = new[] { "Message text is required." };
82	        }
83	
84	        return errors;
85	    }
86	
87	    public async Task<SubmitMessageResult> ExecuteAsync(SubmitMessageCommand command, CancellationToken cancellationToken)
88	    {
89	        ArgumentNullException.ThrowIfNull(command);
90	        var errors = Validate(command);
91	        if (errors.Count > 0)
92	        {
93	            return SubmitMessageResult.Invalid(errors);
94	        }
95	
96	        // 1. Store the message, unchanged and once (RULE-9).
97	        var message = await _unitOfWork.ExecuteAsync(
98	            _ =>
99	            {
100	                var received = Message.Receive(command.Sender!, command.Text!, _clock.UtcNow);
101	                _jobs.AddMessage(received);
102	                return Task.FromResult(received);
103	            },
104	            cancellationToken);
105	
106	        // 2. Emergency rules before the model (AD-3); they can only raise urgency (AD-4).
107	        var hits = EmergencyRules.Evaluate(message.Text, message.ReceivedAtUtc);
108	
109	        // 3. Model preparation; never throws for a model problem.
110	        var preparation = await _prepareJob.AskAsync(message, cancellationToken);
111	
112	        // 4. Jobs, follow-ups and the tenant's acknowledgement (R16). Saved even if the caller has gone away, so the stored message always gets its jobs.
113	        var jobs = await _unitOfWork.ExecuteAsync(
114	            ct => MakeJobsAsync(message, hits, preparation, ct),
115	            CancellationToken.None);
116	
117	        return SubmitMessageResult.Created(message.Id, jobs);
118	    }
119	
120	    private async Task<IReadOnlyList<SubmittedJob>> MakeJobsAsync(
121	        Message message,
122	        IReadOnlyList<RuleHit> hits,
123	        ModelPreparation preparation,
124	        CancellationToken cancellationToken)
125	    {
126	        var response = preparation.Response;
127	        if (response is null)
128	        {
129	            var failed = await NewJobAsync(message, hits, null, cancellationToken);
130	            PrepareJob.RecordFailure(failed, preparation, _clock.UtcNow);
131	            _acknowledge.Send(message, hits, new[] { failed }, _clock.UtcNow);
132	            return new[] { new SubmittedJob(failed.Id, failed.Reference, false) };
133	        }
134	
135	        if (response.Issues.Count == 0)
136	        {
137	            var flagged = await NewJobAsync(message, hits, null, cancellationToken);
138	            PrepareJob.RecordNotMaintenance(flagged, preparation, _clock.UtcNow);
139	            _acknowledge.Send(message, hits, new[] { flagged }, _clock.UtcNow);
140	            return new[] { new SubmittedJob(flagged.Id, flagged.Reference, false) };
141	        }
142	
143	        var resolver = new PropertyResolver(await _properties.ListAsync(cancellationToken));
144	        var matches = response.Issues.Select(i => resolver.Resolve(i.PropertyText)).ToList();
145	        var propertyIds = matches.Where(m => m.IsResolved).Select(m => m.Property!.Id).Distinct().ToList();
146	        var candidates = propertyIds.Count == 0
147	            ? Array.Empty<Job>()
148	            : await _jobs.ListOpenAtPropertiesAsync(
149	                propertyIds,
150	                message.ReceivedAtUtc - FollowUpMatcher.Window,
151	                cancellationToken);
152	
153	        var result = new List<SubmittedJob>();
154	        var created = new List<Job>();
155	        var followUps = new Dictionary<Job, Urgency>();
156	        for (var index = 0; index < response.Issues.Count; index++)
157	        {
158	            var issue = response.Issues[index];
159	            var property = matches[index];
160	            var category = PrepareJob.CategoryFor(issue, property);
161	
162	            // Only jobs that existed before this message are candidates: the model's split stands within a message.
163	            var existing = FollowUpMatcher.Match(candidates, property.Property?.Id, category, message.ReceivedAtUtc);
164	            if (existing is not null)
165	            {
166	                followUps[existing] = followUps.TryGetValue(existing, out var raised) && raised > issue.Urgency
167	                    ? raised
168	                    : issue.Urgency;
169	                result.Add(new SubmittedJob(existing.Id, existing.Reference, true));
170	                continue;
171	            }
172	
173	            var job = await NewJobAsync(message, hits, property.Property?.Id, cancellationToken);
174	            PrepareJob.RecordIssue(job, preparation, index, property, _clock.UtcNow);
175	            created.Add(job);
176	            result.Add(new SubmittedJob(job.Id, job.Reference, false));
177	        }
178	
179	        foreach (var (job, urgency) in followUps)
180	        {
181	            job.AttachFollowUp(message, urgency, _clock.UtcNow);
182	            job.ApplyRules(hits, _clock.UtcNow);
183	        }
184	
185	        // Two issues attached to the same job are one follow-up.
186	        var touched = result.DistinctBy(j => j.JobId).ToList();
187	        var jobsById = followUps.Keys.Concat(created).ToDictionary(j => j.Id);
188	        _acknowledge.Send(message, hits, touched.Select(j => jobsById[j.JobId]).ToList(), _clock.UtcNow);
189	        return touched;
190	    }
191	
192	    private async Task<Job> NewJobAsync(Message message, IReadOnlyList<RuleHit> hits, Guid? propertyId, CancellationToken cancellationToken)
193	    {
194	        var number = await _jobs.NextJobNumberAsync(cancellationToken);
195	        var job = Job.CreateFromMessage(message, JobReference.FromNumber(number), _clock.UtcNow, propertyId);
196	        job.ApplyRules(hits, _clock.UtcNow);
197	        _jobs.Add(job);
198	        return job;
199	    }
200	}
