14	public static class DependencyInjection
15	{
16	    public const string ConnectionStringName = "Meridian";
17	    public const string DefaultConnectionString = "Data Source=meridian.db";
18	    public const string OpenRouterReferer = "http://localhost";
19	    public const string OpenRouterTitle = "meridian-triage";
20	
21	    /// <param name="services">The service collection.</param>
22	    /// <param name="openRouterApiKey">
23	    /// Supplies the OpenRouter key. Defaults to the <c>OPENROUTER_API_KEY</c> environment variable; tests pass their own.
24	    /// </param>
25	    public static IServiceCollection AddMeridianInfrastructure(
26	        this IServiceCollection services,
27	        Func<string?>? openRouterApiKey = null)
28	    {
29	        var readApiKey = openRouterApiKey ?? TriageOptions.ReadApiKey;
30	
31	        services.AddDbContext<MeridianDbContext>((sp, options) =>
32	        {
33	            var configuration = sp.GetRequiredService<IConfiguration>();
34	            var connectionString = configuration.GetConnectionString(ConnectionStringName) ?? DefaultConnectionString;
35	            options.UseSqlite(connectionString);
36	        });
37	
38	        services.AddScoped<IJobRepository, JobRepository>();
39	        services.AddScoped<IPropertyRepository, PropertyRepository>();
40	        services.AddScoped<IUnitOfWork, EfUnitOfWork>();
41	        services.AddScoped<IOutbox, SimulatedOutbox>();
42	        services.AddSingleton<IClock, SystemClock>();
43	
44	        // AD-1: the recorded-response stub is the default; OpenRouter only when the key is set (or Triage:Provider says so).
45	        services.AddHttpClient(OpenRouterTriageModel.HttpClientName, (sp, client) =>
46	            {
47	                var options = TriageOptions.From(sp.GetRequiredService<IConfiguration>());
48	                client.BaseAddress = new Uri(options.OpenRouterBaseUrl.TrimEnd('/') + "/");
49	                var key = readApiKey();
50	                if (key is not null)
51	                {
52	                    client.DefaultRequestHeaders.TryAddWithoutValidation("Authorization", $"Bearer {key}");
53	                }
54	
55	                client.DefaultRequestHeaders.TryAddWithoutValidation("HTTP-Referer", OpenRouterReferer);
56	                client.DefaultRequestHeaders.TryAddWithoutValidation("X-Title", OpenRouterTitle);
57	            })
58	            .RedactLoggedHeaders(_ => true);
59	
60	        services.AddSingleton<ITriageModel>(sp =>
61	        {
62	            var options = TriageOptions.From(sp.GetRequiredService<IConfiguration>());
63	            if (!options.UsesOpenRouter(readApiKey()))
64	            {
65	                return StubTriageModel.FromDirectory(StubTriageModel.DefaultDirectory);
66	            }
67	
68	            return new OpenRouterTriageModel(
69	                sp.GetRequiredService<IHttpClientFactory>(),
70	                options.Model,
71	                OpenRouterTriageModel.LoadSystemPrompt(),
72	                sp.GetService<ILogger<OpenRouterTriageModel>>());
73	        });
74	        return services;
75	    }
76	
77	    /// <summary>
78	    /// Applies pending EF migrations (creates the database on first run), then seeds buildings and properties when
79	    /// there are none (<see cref="SeedData"/>).
80	    /// </summary>
81	    public static async Task MigrateMeridianDatabaseAsync(this IServiceProvider services, CancellationToken cancellationToken = default)
82	    {
83	        await using var scope = services.CreateAsyncScope();
84	        var db = scope.ServiceProvider.GetRequiredService<MeridianDbContext>();
85	        await db.Database.MigrateAsync(cancellationToken);
86	        await SeedData.EnsureSeededAsync(db, cancellationToken);
87	    }
88	}
