1	using System.Diagnostics;
2	using System.Security.Cryptography;
3	using System.Text;
4	using System.Text.Json;
5	using Meridian.Application.Triage;
6	
7	namespace Meridian.Infrastructure.Triage;
8	
9	/// <summary>
10	/// The default model adapter (AD-1): answers from recorded responses instead of calling a provider.
11	/// Each file in <c>Triage/Recorded/*.json</c> holds <c>text</c> and <c>response</c>; a request is matched by the
12	/// SHA-256 of its whitespace-trimmed text. The recorded <c>response</c> is returned as raw JSON, unvalidated, so it
13	/// goes through the same validator as a real model's output.
14	/// </summary>
15	public sealed class StubTriageModel : ITriageModel
16	{
17	    public const string StubModelId = "stub";
18	
19	    /// <summary>Where the recorded responses are copied in the build output.</summary>
20	    public static readonly string DefaultDirectory = Path.Combine(AppContext.BaseDirectory, "Triage", "Recorded");
21	
22	    private readonly IReadOnlyDictionary<string, string> _responsesByHash;
23	
24	    public StubTriageModel(IReadOnlyDictionary<string, string> responsesByTextHash)
25	    {
26	        _responsesByHash = responsesByTextHash;
27	    }
28	
29	    public string ModelId => StubModelId;
30	
31	    public string PromptVersion => TriageContract.Version;
32	
33	    /// <summary>Number of recorded responses loaded.</summary>
34	    public int Count => _responsesByHash.Count;
35	
36	    /// <summary>Loads every <c>*.json</c> file in <paramref name="directory"/>. A missing directory gives an empty stub.</summary>
37	    public static StubTriageModel FromDirectory(string directory)
38	    {
39	        var responses = new Dictionary<string, string>(StringComparer.Ordinal);
40	        if (Directory.Exists(directory))
41	        {
42	            foreach (var path in Directory.EnumerateFiles(directory, "*.json").Order(StringComparer.Ordinal))
43	            {
44	                var (text, response) = ReadRecording(path);
45	                if (!responses.TryAdd(Hash(text), response))
46	                {
47	                    throw new InvalidDataException($"Recorded response {Path.GetFileName(path)} duplicates the text of another recording.");
48	                }
49	            }
50	        }
51	
52	        return new StubTriageModel(responses);
53	    }
54	
55	    /// <summary>Lowercase hex SHA-256 of the UTF-8 bytes of the trimmed text.</summary>
56	    public static string Hash(string text) =>
57	        Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text.Trim()))).ToLowerInvariant();
58	
59	    public Task<TriageModelResult> PrepareAsync(TriageRequest request, CancellationToken cancellationToken)
60	    {
61	        ArgumentNullException.ThrowIfNull(request);
62	        cancellationToken.ThrowIfCancellationRequested();
63	        var watch = Stopwatch.StartNew();
64	        var result = _responsesByHash.TryGetValue(Hash(request.Text), out var raw)
65	            ? TriageModelResult.Output(raw, ModelId, PromptVersion, watch.ElapsedMilliseconds)
66	            : TriageModelResult.Failure(TriageFailureReasons.NoRecordedResponse, ModelId, PromptVersion, watch.ElapsedMilliseconds);
67	        return Task.FromResult(result);
68	    }
69	
70	    private static (string Text, string Response) ReadRecording(string path)
71	    {
72	        using var document = JsonDocument.Parse(File.ReadAllText(path, Encoding.UTF8));
73	        var root = document.RootElement;
74	        if (root.ValueKind != JsonValueKind.Object
75	            || !root.TryGetProperty("text", out var text) || text.ValueKind != JsonValueKind.String
76	            || !root.TryGetProperty("response", out var response))
77	        {
78	            throw new InvalidDataException($"Recorded response {Path.GetFileName(path)} needs a string 'text' and a 'response'.");
79	        }
80	
81	        // A string response is returned as is (lets a recording hold deliberately malformed output).
82	        var raw = response.ValueKind == JsonValueKind.String ? response.GetString()! : response.GetRawText();
83	        return (text.GetString()!, raw);
84	    }
85	}
