1	namespace Meridian.Application.Triage;
2	
3	/// <summary>
4	/// The one port to a model (AD-1). Only <c>Meridian.Infrastructure</c> implements it; everything else calls it.
5	/// </summary>
6	public interface ITriageModel
7	{
8	    /// <summary>The model id recorded in events (e.g. <c>stub</c>), also when a call fails without a result.</summary>
9	    string ModelId { get; }
10	
11	    /// <summary>The prompt and contract version (e.g. <c>triage.v1</c>).</summary>
12	    string PromptVersion { get; }
13	
14	    /// <summary>
15	    /// Asks the model to prepare one message. Returns the raw output unvalidated; the caller validates it
16	    /// with <see cref="TriageValidator"/>. May throw or be cancelled; the caller treats that as unavailable.
17	    /// </summary>
18	    Task<TriageModelResult> PrepareAsync(TriageRequest request, CancellationToken cancellationToken);
19	}
20	
21	/// <summary>What the model is given: the message text and received time only, nothing about the sender (AD-10).</summary>
22	public sealed record TriageRequest(string Text, DateTime ReceivedAtUtc);
23	
24	/// <summary>One model call's outcome, for validation and the event log (AD-2).</summary>
25	/// <param name="Succeeded">True when the model returned output (which may still fail validation).</param>
26	/// <param name="RawOutput">The model's raw text, unvalidated. Null when it returned nothing.</param>
27	/// <param name="FailureReason">Why there is no output, e.g. <c>no-recorded-response</c> or <c>unavailable</c>.</param>
28	public sealed record TriageModelResult(
29	    bool Succeeded,
30	    string? RawOutput,
31	    string ModelId,
32	    string PromptVersion,
33	    long LatencyMs,
34	    int? InputTokens,
35	    int? OutputTokens,
36	    string? FailureReason)
37	{
38	    public static TriageModelResult Output(
39	        string rawOutput,
40	        string modelId,
41	        string promptVersion,
42	        long latencyMs,
43	        int? inputTokens = null,
44	        int? outputTokens = null) =>
45	        new(true, rawOutput, modelId, promptVersion, latencyMs, inputTokens, outputTokens, null);
46	
47	    public static TriageModelResult Failure(string reason, string modelId, string promptVersion, long latencyMs) =>
48	        new(false, null, modelId, promptVersion, latencyMs, null, null, reason);
49	}
50	
51	/// <summary>Failure reasons written to <c>ModelPreparationFailed</c> events.</summary>
52	public static class TriageFailureReasons
53	{
54	    public const string Timeout = "timeout";
55	    public const string Unavailable = "unavailable";
56	    public const string NoRecordedResponse = "no-recorded-response";
57	    public const string InvalidOutput = "invalid-output";
58	    public const string Cancelled = "cancelled";
59	
60	    /// <summary>Intake stopped before the message's jobs were saved; recovery made the job without asking the model.</summary>
61	    public const string Interrupted = "interrupted";
62	}
