1	using System.Diagnostics;
2	using System.Text.Json;
3	using Meridian.Domain.Jobs;
4	using Meridian.Domain.Messages;
5	
6	namespace Meridian.Application.Triage;
7	
8	/// <summary>Settings for <see cref="PrepareJob"/>. Defaults are the product's (AD-3: 20 s).</summary>
9	public sealed class PrepareJobOptions
10	{
11	    public static readonly TimeSpan DefaultTimeout = TimeSpan.FromSeconds(20);
12	
13	    /// <summary>Budget for the whole preparation step, both attempts included.</summary>
14	    public TimeSpan Timeout { get; init; } = DefaultTimeout;
15	}
16	
17	/// <summary>
18	/// The model step's result for one message (AD-2): the validated answer, or why there is none, with every attempt
19	/// for the event log. <see cref="PrepareJob"/> records it on each job the message makes.
20	/// </summary>
21	public sealed class ModelPreparation
22	{
23	    internal ModelPreparation(
24	        TriageResponse? response,
25	        string? failureReason,
26	        IReadOnlyList<object> attempts,
27	        string modelId,
28	        string promptVersion,
29	        long totalLatencyMs)
30	    {
31	        Response = response;
32	        FailureReason = failureReason;
33	        AttemptRecords = attempts;
34	        ModelId = modelId;
35	        PromptVersion = promptVersion;
36	        TotalLatencyMs = totalLatencyMs;
37	    }
38	
39	    /// <summary>The validated answer; null when the model failed (RULE-11, R10).</summary>
40	    public TriageResponse? Response { get; }
41	
42	    public bool Prepared => Response is not null;
43	
44	    public string? FailureReason { get; }
45	
46	    public int Attempts => AttemptRecords.Count;
47	
48	    public string ModelId { get; }
49	
50	    public string PromptVersion { get; }
51	
52	    public long TotalLatencyMs { get; }
53	
54	    internal IReadOnlyList<object> AttemptRecords { get; }
55	
56	    /// <summary>The model outcome event payload: model metadata, every attempt, and what was applied to the job.</summary>
57	    public string Payload(object? applied) => JsonSerializer.Serialize(new
58	    {
59	        modelId = ModelId,
60	        promptVersion = PromptVersion,
61	        attemptCount = Attempts,
62	        latencyMs = TotalLatencyMs,
63	        reason = FailureReason,
64	        applied,
65	        attempts = AttemptRecords,
66	    });
67	}
68	
69	/// <summary>
70	/// The model preparation step of the pipeline (AD-3): asks <see cref="ITriageModel"/> about a stored message and
71	/// validates the answer against <c>triage.v1</c> with one retry for invalid output. Never throws for a model problem.
72	/// Deterministic code then turns the answer into jobs (<see cref="Meridian.Application.Messages.SubmitMessage"/>); the <c>Record*</c>
73	/// methods write the outcome on a job, so every job ends with exactly one <c>ModelPrepared</c> or
74	/// <c>ModelPreparationFailed</c> event.
75	/// </summary>
76	public sealed class PrepareJob
77	{
78	    public const int MaxAttempts = 2;
79	
80	    private readonly ITriageModel _model;
81	    private readonly TimeSpan _timeout;
82	
83	    public PrepareJob(ITriageModel model, PrepareJobOptions? options = null)
84	    {
85	        _model = model;
86	        _timeout = (options ?? new PrepareJobOptions()).Timeout;
87	    }
88	
89	    /// <summary>Asks the model about <paramref name="message"/>: its text and received time only (AD-10).</summary>
90	    public async Task<ModelPreparation> AskAsync(Message message, CancellationToken cancellationToken)
91	    {
92	        ArgumentNullException.ThrowIfNull(message);
93	        var run = await AskModelAsync(new TriageRequest(message.Text, message.ReceivedAtUtc), cancellationToken);
94	        var last = run.Attempts.LastOrDefault();
95	        return new ModelPreparation(
96	            run.Response,
97	            run.FailureReason,
98	            run.Attempts.Select(a => (object)new
99	            {
100	                attempt = a.Attempt,
101	                modelId = a.ModelId ?? _model.ModelId,
102	                promptVersion = a.PromptVersion ?? _model.PromptVersion,
103	                latencyMs = a.LatencyMs,
104	                inputTokens = a.InputTokens,
105	                outputTokens = a.OutputTokens,
106	                rawOutput = a.RawOutput,
107	                failureReason = a.FailureReason,
108	                exceptionType = a.ExceptionType,
109	                validationErrors = a.ValidationErrors,
110	            }).ToList(),
111	            last?.ModelId ?? _model.ModelId,
112	            last?.PromptVersion ?? _model.PromptVersion,
113	            run.TotalLatencyMs);
114	    }
