116	    /// <summary>
117	    /// The category a job gets for <paramref name="issue"/>: Unsure when the model is not confident or the
118	    /// property is not resolved (AD-13), otherwise the proposed category.
119	    /// </summary>
120	    public static Category CategoryFor(TriageIssue issue, PropertyMatch property) =>
121	        issue.Confidence == TriageConfidence.Low || !property.IsResolved ? Category.Unsure : issue.Category;
122	
123	    /// <summary>Applies one issue of a valid answer to a new job made for it.</summary>
124	    public static void RecordIssue(Job job, ModelPreparation preparation, int issueIndex, PropertyMatch property, DateTime nowUtc)
125	    {
126	        var response = preparation.Response ?? throw new InvalidOperationException("The model gave no answer.");
127	        var issue = response.Issues[issueIndex];
128	        var category = CategoryFor(issue, property);
129	        var applied = new
130	        {
131	            category = category.ToString(),
132	            proposedCategory = issue.Category.ToString(),
133	            proposedUrgency = issue.Urgency.ToString(),
134	            confidence = issue.Confidence.ToString().ToLowerInvariant(),
135	            issueCount = response.Issues.Count,
136	            issueIndex,
137	            propertyText = issue.PropertyText,
138	            propertyResolution = property.Resolution.ToString(),
139	            propertyId = property.Property?.Id,
140	        };
141	
142	        job.ApplyModelPreparation(
143	            category,
144	            issue.Urgency,
145	            issue.Explanation,
146	            issue.SummaryEn,
147	            response.Language,
148	            preparation.Payload(applied),
149	            nowUtc);
150	    }
151	
152	    /// <summary>Records a valid answer with no issues: the job stays Unsure and is flagged for a person.</summary>
153	    public static void RecordNotMaintenance(Job job, ModelPreparation preparation, DateTime nowUtc)
154	    {
155	        var response = preparation.Response ?? throw new InvalidOperationException("The model gave no answer.");
156	        var applied = new { category = Category.Unsure.ToString(), issueCount = 0, notMaintenance = true };
157	        job.ApplyNotMaintenance(response.Language, preparation.Payload(applied), nowUtc);
158	    }
159	
160	    /// <summary>Records a model failure: the job stays Unsure with its urgency (RULE-11).</summary>
161	    public static void RecordFailure(Job job, ModelPreparation preparation, DateTime nowUtc) =>
162	        job.RecordModelFailure(preparation.Payload(applied: null), nowUtc);
163	
164	    private async Task<ModelRun> AskModelAsync(TriageRequest request, CancellationToken cancellationToken)
165	    {
166	        var attempts = new List<AttemptRecord>();
167	        var total = Stopwatch.StartNew();
168	        using var timeout = new CancellationTokenSource(_timeout);
169	        using var linked = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, timeout.Token);
170	
171	        for (var attempt = 1; attempt <= MaxAttempts; attempt++)
172	        {
173	            var watch = Stopwatch.StartNew();
174	            TriageModelResult result;
175	            try
176	            {
177	                // WaitAsync enforces the budget even if an adapter ignores the token.
178	                result = await _model.PrepareAsync(request, linked.Token).WaitAsync(linked.Token);
179	            }
180	            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
181	            {
182	                attempts.Add(AttemptRecord.Failed(attempt, watch.ElapsedMilliseconds, TriageFailureReasons.Cancelled));
183	                return ModelRun.Failed(attempts, TriageFailureReasons.Cancelled, total.ElapsedMilliseconds);
184	            }
185	            catch (OperationCanceledException) when (timeout.IsCancellationRequested)
186	            {
187	                attempts.Add(AttemptRecord.Failed(attempt, watch.ElapsedMilliseconds, TriageFailureReasons.Timeout));
188	                return ModelRun.Failed(attempts, TriageFailureReasons.Timeout, total.ElapsedMilliseconds);
189	            }
190	            catch (Exception ex)
191	            {
192	                // Only the exception type is kept: messages may echo tenant text.
193	                attempts.Add(AttemptRecord.Failed(attempt, watch.ElapsedMilliseconds, TriageFailureReasons.Unavailable, ex.GetType().Name));
194	                return ModelRun.Failed(attempts, TriageFailureReasons.Unavailable, total.ElapsedMilliseconds);
195	            }
196	
197	            if (!result.Succeeded)
198	            {
199	                var reason = string.IsNullOrWhiteSpace(result.FailureReason) ? TriageFailureReasons.Unavailable : result.FailureReason;
200	                attempts.Add(AttemptRecord.From(attempt, result, reason, Array.Empty<string>()));
201	                return ModelRun.Failed(attempts, reason, total.ElapsedMilliseconds);
202	            }
203	
204	            var validation = TriageValidator.Validate(result.RawOutput);
205	            attempts.Add(AttemptRecord.From(attempt, result, null, validation.Errors));
206	            if (validation.IsValid)
207	            {
208	                return ModelRun.Succeeded(attempts, validation.Response!, total.ElapsedMilliseconds);
209	            }
210	        }
211	
212	        return ModelRun.Failed(attempts, TriageFailureReasons.InvalidOutput, total.ElapsedMilliseconds);
213	    }
214	
215	    private sealed record ModelRun(IReadOnlyList<AttemptRecord> Attempts, TriageResponse? Response, string? FailureReason, long TotalLatencyMs)
216	    {
217	        public static ModelRun Succeeded(IReadOnlyList<AttemptRecord> attempts, TriageResponse response, long latencyMs) =>
218	            new(attempts, response, null, latencyMs);
219	
220	        public static ModelRun Failed(IReadOnlyList<AttemptRecord> attempts, string reason, long latencyMs) =>
221	            new(attempts, null, reason, latencyMs);
222	    }
223	
224	    private sealed record AttemptRecord(
225	        int Attempt,
226	        string? ModelId,
227	        string? PromptVersion,
228	        long LatencyMs,
229	        int? InputTokens,
230	        int? OutputTokens,
231	        string? RawOutput,
232	        string? FailureReason,
233	        string? ExceptionType,
234	        IReadOnlyList<string> ValidationErrors)
235	    {
236	        public static AttemptRecord Failed(int attempt, long latencyMs, string reason, string? exceptionType = null) =>
237	            new(attempt, null, null, latencyMs, null, null, null, reason, exceptionType, Array.Empty<string>());
238	
239	        public static AttemptRecord From(int attempt, TriageModelResult result, string? reason, IReadOnlyList<string> errors) =>
240	            new(attempt, result.ModelId, result.PromptVersion, result.LatencyMs, result.InputTokens, result.OutputTokens,
241	                result.RawOutput, reason, null, errors);
242	    }
243	}
