7	/// <summary>
8	/// One unit of maintenance work. State changes only through methods on this class,
9	/// and every change appends a <see cref="JobEvent"/> (AD-5).
10	/// </summary>
11	public sealed class Job
12	{
13	    private readonly List<Message> _messages = new();
14	    private readonly List<JobEvent> _events = new();
15	
16	    /// <summary>Fired rule ids, comma-separated, in the order they first fired; stored as the <c>RuleIds</c> column.</summary>
17	    private string _ruleIds = string.Empty;
18	
19	    private Job()
20	    {
21	        Reference = string.Empty;
22	    }
23	
24	    public Guid Id { get; private set; }
25	
26	    public string Reference { get; private set; }
27	
28	    public JobStatus Status { get; private set; }
29	
30	    public Urgency Urgency { get; private set; }
31	
32	    public Category Category { get; private set; }
33	
34	    /// <summary>The property the job is at, once <c>PropertyResolver</c> matched one (AD-13); null when unresolved.</summary>
35	    public Guid? PropertyId { get; private set; }
36	
37	    /// <summary>When the job's first message was received (UTC).</summary>
38	    public DateTime ReceivedAtUtc { get; private set; }
39	
40	    /// <summary>When the job was opened (UTC).</summary>
41	    public DateTime CreatedAtUtc { get; private set; }
42	
43	    /// <summary>Why the job was prepared this way, from the model's proposal (R7). Null until prepared.</summary>
44	    public string? Explanation { get; private set; }
45	
46	    /// <summary>English summary of the issue, from the model's proposal. Null until prepared.</summary>
47	    public string? SummaryEn { get; private set; }
48	
49	    /// <summary>Language of the tenant's message as reported by the model (e.g. <c>pl</c>). Null until prepared.</summary>
50	    public string? Language { get; private set; }
51	
52	    /// <summary>Ids of the emergency rules that fired on this job's messages (see <see cref="EmergencyRuleIds"/>), for the job view.</summary>
53	    public IReadOnlyList<string> RuleIds =>
54	        _ruleIds.Length == 0 ? Array.Empty<string>() : _ruleIds.Split(RuleIdSeparator);
55	
56	    /// <summary>The job's messages: the first plus any follow-ups. A message may also belong to other jobs.</summary>
57	    public IReadOnlyList<Message> Messages => _messages;
58	
59	    /// <summary>Messages attached after the first one (R8).</summary>
60	    public int FollowUpCount => Math.Max(0, _messages.Count - 1);
61	
62	    /// <summary>True while the job can still take follow-ups: not <see cref="JobStatus.Attended"/> or <see cref="JobStatus.Rejected"/>.</summary>
63	    public bool IsOpen => Status is not (JobStatus.Attended or JobStatus.Rejected);
64	
65	    public IReadOnlyList<JobEvent> Events => _events;
66	
67	    /// <summary>
68	    /// Creates a job for one issue of a received message (or the message as a whole when there is no usable issue):
69	    /// status Prepared, category Unsure, urgency Routine. Appends <see cref="EventType.MessageReceived"/> then
70	    /// <see cref="EventType.JobPrepared"/>. A message can start several jobs.
71	    /// </summary>
72	    /// <param name="message">The received message; it becomes the job's first message.</param>
73	    /// <param name="reference">The job reference, e.g. <c>MER-000001</c>.</param>
74	    /// <param name="nowUtc">The current time from the application's clock port (AD-9).</param>
75	    /// <param name="propertyId">The resolved property, or null when it is unresolved (AD-13).</param>
76	    public static Job CreateFromMessage(Message message, string reference, DateTime nowUtc, Guid? propertyId = null)
77	    {
78	        ArgumentNullException.ThrowIfNull(message);
79	        if (string.IsNullOrWhiteSpace(reference) || !reference.StartsWith(JobReference.Prefix, StringComparison.Ordinal))
80	        {
81	            throw new ArgumentException("Reference must start with " + JobReference.Prefix + ".", nameof(reference));
82	        }
83	
84	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
85	        if (propertyId == Guid.Empty)
86	        {
87	            throw new ArgumentException("Property id must not be empty; pass null when unresolved.", nameof(propertyId));
88	        }
89	
90	        var job = new Job
91	        {
92	            Id = Guid.NewGuid(),
93	            Reference = reference,
94	            Status = JobStatus.Prepared,
95	            Urgency = Urgency.Routine,
96	            Category = Category.Unsure,
97	            ReceivedAtUtc = message.ReceivedAtUtc,
98	            CreatedAtUtc = nowUtc,
99	            PropertyId = propertyId,
100	        };
101	
102	        job._messages.Add(message);
103	
104	        job.Append(
105	            EventType.MessageReceived,
106	            message.ReceivedAtUtc,
107	            JobEvent.SystemActor,
108	            new { messageId = message.Id });
109	
110	        job.Append(
111	            EventType.JobPrepared,
112	            nowUtc,
113	            JobEvent.SystemActor,
114	            new
115	            {
116	                reference = job.Reference,
117	                status = job.Status.ToString(),
118	                urgency = job.Urgency.ToString(),
119	                category = job.Category.ToString(),
120	                propertyId = job.PropertyId,
121	            });
122	
123	        return job;
124	    }
125	
126	    /// <summary>
127	    /// Attaches a later message to this open job as a follow-up (R8, AD-13): links the message, appends
128	    /// <see cref="EventType.FollowUpAttached"/> with the message id and this job's reference, then raises urgency to
129	    /// <paramref name="proposal"/> through <see cref="RaiseUrgency"/> (never lowers it, AD-4).
130	    /// </summary>
131	    /// <param name="proposal">The urgency proposed for the follow-up's issue.</param>
132	    public void AttachFollowUp(Message message, Urgency proposal, DateTime nowUtc)
133	    {
134	        ArgumentNullException.ThrowIfNull(message);
135	        if (!Enum.IsDefined(proposal))
136	        {
137	            throw new ArgumentOutOfRangeException(nameof(proposal), proposal, "Unknown urgency.");
138	        }
139	
140	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
141	        if (!IsOpen)
142	        {
143	            throw new InvalidOperationException($"Job {Reference} is {Status} and cannot take follow-ups.");
144	        }
145	
146	        if (_messages.Any(m => m.Id == message.Id))
147	        {
148	            throw new InvalidOperationException("The message is already on this job.");
149	        }
150	
151	        _messages.Add(message);
152	        Append(
153	            EventType.FollowUpAttached,
154	            nowUtc,
155	            JobEvent.SystemActor,
156	            new { messageId = message.Id, reference = Reference, proposedUrgency = proposal.ToString() });
157	        RaiseUrgency(proposal, FollowUpReason, nowUtc);
158	    }
159	
160	    /// <summary>Explanation shown on a job whose message the model found no maintenance problem in.</summary>
161	    public const string NotMaintenanceExplanation =
162	        "The AI found no maintenance problem in this message. A person should check it.";
163	
164	    /// <summary>True once a <see cref="EventType.ModelPrepared"/> or <see cref="EventType.ModelPreparationFailed"/> event exists.</summary>
165	    public bool HasModelOutcome =>
166	        _events.Any(e => e.Type is EventType.ModelPrepared or EventType.ModelPreparationFailed);
167	
168	    /// <summary>
169	    /// Applies a validated model proposal: sets category, explanation, English summary and language, appends
170	    /// <see cref="EventType.ModelPrepared"/> with <paramref name="payloadJson"/>, then raises urgency to the
171	    /// proposal (never lowers it, AD-4).
172	    /// </summary>
173	    /// <param name="payloadJson">Event payload with the model metadata (model id, prompt version, latency, raw output, attempts).</param>
174	    public void ApplyModelPreparation(
175	        Category category,
176	        Urgency urgency,
177	        string explanation,
178	        string summaryEn,
179	        string language,
180	        string payloadJson,
181	        DateTime nowUtc)
182	    {
183	        RequireNoModelOutcome();
184	        if (string.IsNullOrWhiteSpace(explanation))
185	        {
186	            throw new ArgumentException("Explanation is required.", nameof(explanation));
187	        }
188	
189	        if (string.IsNullOrWhiteSpace(summaryEn))
190	        {
191	            throw new ArgumentException("English summary is required.", nameof(summaryEn));
192	        }
193	
194	        if (string.IsNullOrWhiteSpace(language))
195	        {
196	            throw new ArgumentException("Language is required.", nameof(language));
197	        }
198	
199	        RequireJsonObject(payloadJson, nameof(payloadJson));
200	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
201	
202	        Category = category;
203	        Explanation = explanation;
204	        SummaryEn = summaryEn;
205	        Language = language;
206	        AppendRaw(EventType.ModelPrepared, nowUtc, JobEvent.SystemActor, payloadJson);
207	        RaiseUrgency(urgency, "model", nowUtc);
208	    }
209	
210	    /// <summary>
211	    /// Records a valid model answer with no issues (not maintenance): the job keeps category Unsure and its urgency,
212	    /// is flagged for a person with <see cref="NotMaintenanceExplanation"/>, and gets <see cref="EventType.ModelPrepared"/>.
213	    /// </summary>
214	    public void ApplyNotMaintenance(string language, string payloadJson, DateTime nowUtc)
215	    {
216	        RequireNoModelOutcome();
217	        if (string.IsNullOrWhiteSpace(language))
218	        {
219	            throw new ArgumentException("Language is required.", nameof(language));
220	        }
221	
222	        RequireJsonObject(payloadJson, nameof(payloadJson));
223	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
224	        Category = Category.Unsure;
225	        Language = language;
226	        Explanation = NotMaintenanceExplanation;
227	        AppendRaw(EventType.ModelPrepared, nowUtc, JobEvent.SystemActor, payloadJson);
228	    }
229	
230	    /// <summary>
231	    /// Records that the model gave no usable proposal. The job keeps category Unsure and its urgency (RULE-11).
232	    /// </summary>
233	    /// <param name="payloadJson">Event payload with the failure reason, model metadata and validation errors.</param>
234	    public void RecordModelFailure(string payloadJson, DateTime nowUtc)
235	    {
236	        RequireNoModelOutcome();
237	        RequireJsonObject(payloadJson, nameof(payloadJson));
238	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
239	        AppendRaw(EventType.ModelPreparationFailed, nowUtc, JobEvent.SystemActor, payloadJson);
240	    }
241	
242	    /// <summary>
243	    /// Records the emergency rules' result for a message (R4): appends <see cref="EventType.RulesApplied"/> listing
244	    /// each rule id and matched phrase (an empty list when none fired), remembers the fired rule ids, and raises the
245	    /// job to Emergency with reason <c>rule:&lt;id&gt;</c> of the first hit. Never lowers urgency (AD-4).
246	    /// </summary>
247	    /// <param name="hits">The result of <see cref="EmergencyRules.Evaluate"/>.</param>
248	    public void ApplyRules(IReadOnlyList<RuleHit> hits, DateTime nowUtc)
249	    {
250	        ArgumentNullException.ThrowIfNull(hits);
251	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
252	        foreach (var hit in hits)
253	        {
254	            if (hit is null || !EmergencyRuleIds.All.Contains(hit.RuleId))
255	            {
256	                throw new ArgumentException("Unknown emergency rule.", nameof(hits));
257	            }
258	        }
259	
260	        Append(
261	            EventType.RulesApplied,
262	            nowUtc,
263	            JobEvent.SystemActor,
264	            new { rules = hits.Select(h => new { id = h.RuleId, matchedPhrase = h.MatchedPhrase }) });
265	
266	        if (hits.Count == 0)
267	        {
268	            return;
269	        }
270	
271	        var ruleIds = RuleIds.Concat(hits.Select(h => h.RuleId)).Distinct(StringComparer.Ordinal);
272	        _ruleIds = string.Join(RuleIdSeparator, ruleIds);
273	        RaiseUrgency(Urgency.Emergency, RuleReasonPrefix + hits[0].RuleId, nowUtc);
274	    }
275	
276	    /// <summary>
277	    /// Records that a tenant acknowledgement was written to the outbox (R16, AD-8): appends
278	    /// <see cref="EventType.AcknowledgementSent"/> with the template id and the outbound message id.
279	    /// </summary>
280	    /// <param name="outboundId">The id of the stored outbound message.</param>
281	    /// <param name="templateId">The fixed template it was rendered from, e.g. <c>acknowledgement</c> or <c>gas-safety</c>.</param>
282	    public void RecordAcknowledgement(Guid outboundId, string templateId, DateTime nowUtc)
283	    {
284	        if (outboundId == Guid.Empty)
285	        {
286	            throw new ArgumentException("An outbound message id is required.", nameof(outboundId));
287	        }
288	
289	        if (string.IsNullOrWhiteSpace(templateId))
290	        {
291	            throw new ArgumentException("A template id is required.", nameof(templateId));
292	        }
293	
294	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
295	        Append(
296	            EventType.AcknowledgementSent,
297	            nowUtc,
298	            JobEvent.SystemActor,
299	            new { templateId, outboundId });
300	    }
301	
302	    /// <summary>
303	    /// The only way urgency goes down (AD-4): a person sets the urgency to <paramref name="level"/>, higher or lower,
304	    /// and <see cref="EventType.UrgencySetByPerson"/> records who, from what, to what and why. Called from the review
305	    /// use case only.
306	    /// </summary>
307	    /// <param name="actor">The acting person (e.g. Rachel); never the system actor.</param>
308	    /// <param name="reason">Why the person changed it; required.</param>
309	    public void SetUrgencyByPerson(Urgency level, string actor, string reason, DateTime nowUtc)
310	    {
311	        if (!Enum.IsDefined(level))
312	        {
313	            throw new ArgumentOutOfRangeException(nameof(level), level, "Unknown urgency.");
314	        }
315	
316	        if (string.IsNullOrWhiteSpace(actor) || string.Equals(actor.Trim(), JobEvent.SystemActor, StringComparison.OrdinalIgnoreCase))
317	        {
318	            throw new ArgumentException("A person is required.", nameof(actor));
319	        }
320	
321	        if (actor.Length > JobEvent.MaxActorLength)
322	        {
323	            throw new ArgumentException($"Actor must be at most {JobEvent.MaxActorLength} characters.", nameof(actor));
324	        }
325	
326	        if (string.IsNullOrWhiteSpace(reason))
327	        {
328	            throw new ArgumentException("A reason is required.", nameof(reason));
329	        }
330	
331	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
332	        var from = Urgency;
333	        Urgency = level;
334	        Append(
335	            EventType.UrgencySetByPerson,
336	            nowUtc,
337	            actor,
338	            new { from = from.ToString(), to = level.ToString(), reason });
339	    }
340	
341	    /// <summary>
342	    /// The only automatic urgency change (AD-4): raises to <paramref name="level"/> and appends
343	    /// <see cref="EventType.UrgencyRaised"/>; a value lower than or equal to the current urgency is ignored.
344	    /// </summary>
345	    /// <returns>True when the urgency changed.</returns>
346	    public bool RaiseUrgency(Urgency level, string reason, DateTime nowUtc)
347	    {
348	        if (!Enum.IsDefined(level))
349	        {
350	            throw new ArgumentOutOfRangeException(nameof(level), level, "Unknown urgency.");
351	        }
352	
353	        if (string.IsNullOrWhiteSpace(reason))
354	        {
355	            throw new ArgumentException("A reason is required.", nameof(reason));
356	        }
357	
358	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
359	        if (level <= Urgency)
360	        {
361	            return false;
362	        }
363	
364	        var from = Urgency;
365	        Urgency = level;
366	        Append(
367	            EventType.UrgencyRaised,
368	            nowUtc,
369	            JobEvent.SystemActor,
370	            new { from = from.ToString(), to = level.ToString(), reason });
371	        return true;
372	    }
373	
374	    private const char RuleIdSeparator = ',';
375	    private const string RuleReasonPrefix = "rule:";
376	    private const string FollowUpReason = "follow-up";
377	
378	    private void RequireNoModelOutcome()
379	    {
380	        if (HasModelOutcome)
381	        {
382	            throw new InvalidOperationException("The model outcome for this job is already recorded.");
383	        }
384	    }
385	
386	    private static void RequireJsonObject(string payloadJson, string paramName)
387	    {
388	        try
389	        {
390	            using var document = JsonDocument.Parse(payloadJson ?? string.Empty);
391	            if (document.RootElement.ValueKind != JsonValueKind.Object)
392	            {
393	                throw new ArgumentException("Payload must be a JSON object.", paramName);
394	            }
395	        }
396	        catch (JsonException ex)
397	        {
398	            throw new ArgumentException("Payload must be valid JSON.", paramName, ex);
399	        }
400	    }
401	
402	    private void Append(EventType type, DateTime occurredAtUtc, string actor, object payload) =>
403	        AppendRaw(type, occurredAtUtc, actor, JsonSerializer.Serialize(payload));
404	
405	    private void AppendRaw(EventType type, DateTime occurredAtUtc, string actor, string payloadJson) =>
406	        _events.Add(new JobEvent(Id, type, occurredAtUtc, actor, payloadJson));
407	}
