6	namespace Meridian.Application.Triage;
7	
8	/// <summary>How a <c>property_text</c> was resolved.</summary>
9	public enum PropertyResolution
10	{
11	    /// <summary>Exactly one seeded property matched.</summary>
12	    Resolved,
13	
14	    /// <summary>The text names no address.</summary>
15	    NoAddress,
16	
17	    /// <summary>No seeded building matched, or the building matched but the flat is not one Meridian knows.</summary>
18	    Unresolved,
19	
20	    /// <summary>More than one property could be meant, e.g. a building with several flats and no flat number.</summary>
21	    Ambiguous,
22	}
23	
24	/// <summary>The resolver's answer: the property when exactly one matched, otherwise null.</summary>
25	public sealed record PropertyMatch(PropertyResolution Resolution, Property? Property)
26	{
27	    public static readonly PropertyMatch NoAddress = new(PropertyResolution.NoAddress, null);
28	    public static readonly PropertyMatch Unresolved = new(PropertyResolution.Unresolved, null);
29	    public static readonly PropertyMatch Ambiguous = new(PropertyResolution.Ambiguous, null);
30	
31	    public bool IsResolved => Resolution == PropertyResolution.Resolved;
32	}
33	
34	/// <summary>
35	/// Matches the model's <c>property_text</c> against the seeded properties (AD-13). Plain code, no model call.
36	/// <para>
37	/// The text and each building name are normalised: lower case, accents removed, punctuation (any script) to spaces,
38	/// common abbreviations expanded (<c>st</c>, <c>rd</c>, <c>hse</c>, ...) and unit words dropped in the languages the
39	/// eval set uses (Flat, Apt, Mieszkanie, Apartamentul, فلیٹ). A building matches when its name words appear in order;
40	/// a name that starts with a number (<c>22 Pemberton Road</c>) also needs that number just before them. Remaining
41	/// number tokens (<c>4</c>, <c>14b</c>) pick the flat. Exactly one property → resolved; none or several → null.
42	/// </para>
43	/// </summary>
44	public sealed class PropertyResolver
45	{
46	    private static readonly Regex NumberToken = new("^[0-9]+[a-z]?$", RegexOptions.CultureInvariant, TimeSpan.FromSeconds(1));
47	
48	    private static readonly IReadOnlyDictionary<string, string> Abbreviations = new Dictionary<string, string>(StringComparer.Ordinal)
49	    {
50	        ["st"] = "street",
51	        ["str"] = "street",
52	        ["rd"] = "road",
53	        ["hse"] = "house",
54	        ["ave"] = "avenue",
55	        ["av"] = "avenue",
56	        ["ln"] = "lane",
57	        ["ct"] = "court",
58	        ["crt"] = "court",
59	        ["gr"] = "grove",
60	        ["gro"] = "grove",
61	        ["pl"] = "place",
62	        ["cl"] = "close",
63	    };
64	
65	    private static readonly HashSet<string> UnitWords = new(StringComparer.Ordinal)
66	    {
67	        "flat", "flats", "apt", "apartment", "apartament", "apartamentul", "mieszkanie", "mieszkania", "mieszk",
68	        "unit", "no", "nr", "number",
69	        "\u0641\u0644\u06CC\u0679", // فلیٹ (Urdu, Farsi yeh)
70	        "\u0641\u0644\u064A\u062A", // فليت (Arabic)
71	    };
72	
73	    private readonly IReadOnlyList<BuildingTokens> _buildings;
74	
75	    /// <param name="properties">Every seeded property, each with its <see cref="Property.Building"/> loaded.</param>
76	    public PropertyResolver(IEnumerable<Property> properties)
77	    {
78	        ArgumentNullException.ThrowIfNull(properties);
79	        _buildings = properties
80	            .GroupBy(p => p.BuildingId)
81	            .Select(g =>
82	            {
83	                var building = g.First().Building
84	                    ?? throw new ArgumentException("Every property needs its building loaded.", nameof(properties));
85	                return BuildingTokens.From(building, g.ToList());
86	            })
87	            .ToList();
88	    }
89	
90	    public PropertyMatch Resolve(string? propertyText)
91	    {
92	        var tokens = Tokenize(propertyText);
93	        if (tokens.Count == 0)
94	        {
95	            return PropertyMatch.NoAddress;
96	        }
97	
98	        var matched = _buildings
99	            .Select(b => (Building: b, Consumed: b.Match(tokens)))
100	            .Where(m => m.Consumed is not null)
101	            .ToList();
102	        switch (matched.Count)
103	        {
104	            case 0:
105	                return PropertyMatch.Unresolved;
106	            case > 1:
107	                // Two addresses in one text: a person picks.
108	                return PropertyMatch.Ambiguous;
109	        }
110	
111	        var (building, consumed) = matched[0];
112	        var units = tokens
113	            .Where((t, i) => !consumed!.Contains(i) && NumberToken.IsMatch(t))
114	            .ToHashSet(StringComparer.Ordinal);
115	        if (building.HasFlats && units.Count == 0)
116	        {
117	            // A block named without a flat number could be any of its flats.
118	            return PropertyMatch.Ambiguous;
119	        }
120	
121	        var candidates = building.PropertiesFor(units).ToList();
122	        return candidates.Count switch
123	        {
124	            1 => new PropertyMatch(PropertyResolution.Resolved, candidates[0]),
125	            0 => PropertyMatch.Unresolved,
126	            _ => PropertyMatch.Ambiguous,
127	        };
128	    }
129	
130	    /// <summary>The normalised tokens of <paramref name="text"/>, as the resolver compares them.</summary>
131	    public static IReadOnlyList<string> Tokenize(string? text)
132	    {
133	        if (string.IsNullOrWhiteSpace(text))
134	        {
135	            return Array.Empty<string>();
136	        }
137	
138	        var decomposed = text.Normalize(NormalizationForm.FormD).ToLowerInvariant();
139	        var builder = new StringBuilder(decomposed.Length);
140	        foreach (var c in decomposed)
141	        {
142	            var category = CharUnicodeInfo.GetUnicodeCategory(c);
143	            if (category == UnicodeCategory.NonSpacingMark)
144	            {
145	                continue;
146	            }
147	
148	            builder.Append(char.IsLetterOrDigit(c) ? c : ' ');
149	        }
150	
151	        var tokens = new List<string>();
152	        foreach (var raw in builder.ToString().Normalize(NormalizationForm.FormC).Split(' ', StringSplitOptions.RemoveEmptyEntries))
153	        {
154	            var token = SplitUnitPrefix(raw);
155	            if (token is null || UnitWords.Contains(token))
156	            {
157	                continue;
158	            }
159	
160	            tokens.Add(Abbreviations.TryGetValue(token, out var full) ? full : token);
161	        }
162	
163	        return tokens;
164	    }
165	
166	    /// <summary>Turns <c>flat4</c> into <c>4</c>; leaves other tokens as they are; drops a bare unit word.</summary>
167	    private static string? SplitUnitPrefix(string token)
168	    {
169	        foreach (var word in UnitWords)
170	        {
171	            if (token.Length > word.Length && token.StartsWith(word, StringComparison.Ordinal) && char.IsDigit(token[word.Length]))
172	            {
173	                return token[word.Length..];
174	            }
175	        }
176	
177	        return token;
178	    }
179	
180	    private sealed class BuildingTokens
181	    {
182	        private readonly string? _number;
183	        private readonly IReadOnlyList<string> _words;
184	        private readonly IReadOnlyList<Property> _properties;
185	
186	        private BuildingTokens(string? number, IReadOnlyList<string> words, IReadOnlyList<Property> properties)
187	        {
188	            _number = number;
189	            _words = words;
190	            _properties = properties;
191	        }
192	
193	        public bool HasFlats => _properties.Any(p => p.Unit is not null);
194	
195	        public static BuildingTokens From(Building building, IReadOnlyList<Property> properties)
196	        {
197	            var tokens = Tokenize(building.Name);
198	            var number = tokens.Count > 1 && NumberToken.IsMatch(tokens[0]) ? tokens[0] : null;
199	            var words = number is null ? tokens : tokens.Skip(1).ToList();
200	            if (words.Count == 0)
201	            {
202	                throw new ArgumentException($"Building '{building.Name}' has no name words to match.");
203	            }
204	
205	            return new BuildingTokens(number, words, properties);
206	        }
207	
208	        /// <summary>The token indexes the building name used, or null when it does not appear.</summary>
209	        public HashSet<int>? Match(IReadOnlyList<string> tokens)
210	        {
211	            for (var start = 0; start + _words.Count <= tokens.Count; start++)
212	            {
213	                var all = true;
214	                for (var k = 0; k < _words.Count && all; k++)
215	                {
216	                    all = string.Equals(tokens[start + k], _words[k], StringComparison.Ordinal);
217	                }
218	
219	                if (!all)
220	                {
221	                    continue;
222	                }
223	
224	                var used = Enumerable.Range(start, _words.Count).ToHashSet();
225	                if (_number is null)
226	                {
227	                    return used;
228	                }
229	
230	                if (start > 0 && string.Equals(tokens[start - 1], _number, StringComparison.Ordinal))
231	                {
232	                    used.Add(start - 1);
233	                    return used;
234	                }
235	            }
236	
237	            return null;
238	        }
239	
240	        public IEnumerable<Property> PropertiesFor(IReadOnlySet<string> units)
241	        {
242	            if (!HasFlats)
243	            {
244	                // A house: any extra flat number means a home Meridian does not know.
245	                return units.Count == 0 ? _properties : Array.Empty<Property>();
246	            }
247	
248	            return _properties.Where(p => units.Contains(p.Unit!.ToLowerInvariant()));
249	        }
250	    }
251	}
