        }

        var issues = string.Join(", ", outcome.Issues.Select(i => $"{i.Category}/{i.Urgency}{(i.IsFollowUp ? " (follow-up)" : string.Empty)}"));
        var model = outcome.ModelPrepared ? "model ok" : $"model failed: {outcome.ModelFailureReason ?? "unknown"}";
