                modelCalls = c.Outcome.ModelCalls,
                latencyMs = c.Outcome.LatencyMs,
                inputTokens = c.Outcome.InputTokens,
                outputTokens = c.Outcome.OutputTokens,
                costUsd = c.CostUsd,
                error = c.Outcome.Error,
                failures = c.Failures,
            }),
        };
